{"source": "def simulate(actions, conflict_handling, channel_connections):
    committed = {}
    connections = {
        "main": {"in_transaction": False, "state": None},
        "other": {"in_transaction": False, "state": None}
    }
    total_channel = 0
    for action in actions:
        op = action["op"]
        conn = action.get("connection", "main")
        if op == "begin":
            connections[conn]["in_transaction"] = True
            connections[conn]["state"] = dict(committed)
        elif op == "commit":
            if connections[conn]["in_transaction"]:
                committed = dict(connections[conn]["state"])
                connections[conn]["in_transaction"] = False
                connections[conn]["state"] = None
        elif op == "rollback":
            if connections[conn]["in_transaction"]:
                connections[conn]["in_transaction"] = False
                connections[conn]["state"] = None
        else:
            if connections[conn]["in_transaction"]:
                state = connections[conn]["state"]
            else:
                state = committed
            key = action["key"]
            value = action.get("value", 0)
            changes = 0
            if op == "put":
                if key not in state:
                    changes = 1
                    state[key] = value
                else:
                    if conflict_handling == "replace":
                        changes = 1
                        state[key] = value
            elif op == "update":
                if key in state:
                    changes = 1
                    state[key] = value
            elif op == "delete":
                if key in state:
                    changes = 1
                    state.pop(key, None)
            if channel_connections == "both" or channel_connections == conn:
                total_channel += changes
    committed_count = len(committed)
    committed_sum = sum(committed.values())
    return total_channel, committed_count, committed_sum

def investigate(context, acquire):
    hist = acquire("history")
    if not hist:
        return {"value": None, "unresolved": True}
    matching = []
    for conflict in ["ignore", "replace"]:
        for channel_conn in ["main", "other", "both"]:
            match = True
            for receipt in hist:
                sim_channel, sim_count, sim_sum = simulate(receipt["actions"], conflict, channel_conn)
                obs = receipt["observed"]
                if sim_channel != obs["channel"] or sim_count != obs["committed_count"] or sim_sum != obs["committed_sum"]:
                    match = False
                    break
            if match:
                matching.append((conflict, channel_conn))
    if not matching:
        return {"value": None, "unresolved": True}
    goal = context["goal"]
    actions = context["actions"]
    results = []
    for conflict, channel_conn in matching:
        sim_channel, sim_count, sim_sum = simulate(actions, conflict, channel_conn)
        if goal == "channel":
            results.append(sim_channel)
        elif goal == "committed_count":
            results.append(sim_count)
        elif goal == "committed_sum":
            results.append(sim_sum)
        else:
            return {"value": None, "unresolved": True}
    first = results[0]
    for r in results:
        if r != first:
            return {"value": None, "unresolved": True}
    return {"value": first, "unresolved": False}
